    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first (need their email)", "err");
      return;
    }
    var actionType = action; // "disable_tool" | "enable_tool" | "force_redownload_tool"
    var actionLabel = {
      disable_tool: "Disable",
      enable_tool: "Enable",
      force_redownload_tool: "Force re-download (uninstall + re-install)",
    }[actionType] || actionType;

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Tool</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(toolId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Action</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(actionLabel) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason</label>' +
          '<input type="text" id="_af_tool_reason" placeholder="(optional admin note)">' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      icon: "🛠️",
      title: "Push tool action",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
          },
        },
        {
          label: "Push",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var reason = (document.getElementById("_af_tool_reason").value || "").trim();
            var overrideId = "fleet-" + actionType + "-" + toolId + "-" + userId + "-" + Date.now();
            var entry = {
              id: overrideId,
              audienceEmails: [id.email],
              actions: [{ type: actionType, toolId: toolId }],
              pushedAt: new Date().toISOString(),
              pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
            };
            if (reason) entry.note = reason;
            _toast("⏳ Pushing override…", "info");
            _pushOverride(entry).then(function () {
              _toast("✅ " + actionLabel + " pushed for " + toolId, "ok");
              _renderDashboard();
            }).catch(function (err) {
              _toast("Push failed: " + err.message, "err");
            });
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Tool uninstall (manifest audience removal + force_redownload) ──
  // True uninstall is a TWO-STEP operation:
  //   1. Edit tools-manifest-v3.json — remove user's email from the tool's
  //      audienceEmails. Without this, the user's next sync auto-installs
  //      the tool back (manifest still lists them in audience).
  //   2. Push a force_redownload_tool override targeted at this user. That
  //      action calls eli.tools.uninstall on their machine → removes from
  //      IDB → tile vanishes from their dashboard.
  // Result: tool gone, won't auto-reinstall. To re-grant access later,
  // add the email back to the manifest audience and run Force re-install.
  function _showToolUninstaller(userId, toolId) {
    if (typeof showEliDialog !== "function") return;
    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first (need their email for manifest audience)", "err");
      return;
    }
    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Tool</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(toolId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_warn">⚠️ <b>Permanent uninstall.</b> ' +
        'Two steps: (1) remove user from the manifest audience so it won\'t re-install, ' +
        '(2) push force_redownload to clear from their IDB. ' +
        'To restore access later you\'ll have to manually add the user back to the manifest audience.</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason</label>' +
          '<input type="text" id="_af_uninst_reason" placeholder="(optional admin note)">' +
        '</div>' +
      '</div>';
    showEliDialog({
      variant: "warning",
      icon: "🗑",
      title: "Uninstall tool from user",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
          },
        },
        {
          label: "Uninstall",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var reason = (document.getElementById("_af_uninst_reason").value || "").trim();
            _toast("⏳ Editing manifest…", "info");
            // Step 1: edit tools-manifest-v3.json to exclude this user.
            // Two paths depending on the tool's existing audience:
            //   • Has audienceEmails (per-email inclusion list) — remove
            //     the user's email from it.
            //   • Has audience: ["all"] OR no inclusion list — add the
            //     user's email to audienceEmailExcludes (negative filter,
            //     2026-05-23 kernel addition). Preserves "broadcast to
            //     everyone else" semantics.
            // Result either way: this user no longer matches the audience
            // on next sync → tool won't re-install after the override-
            // driven uninstall.
            _ghGet("tools-manifest-v3.json").then(function (r) {
              if (!r) throw new Error("tools-manifest-v3.json not found on CDN");
              var manifest;
              try { manifest = JSON.parse(_b64ToStr(r.content)); }
              catch (e) { throw new Error("manifest parse failed: " + e.message); }
              var sha = r.sha;
              var tools = manifest && manifest.tools;
              if (!Array.isArray(tools)) throw new Error("manifest has no tools array");
              var entry = tools.find(function (t) { return t && t.id === toolId; });
              if (!entry) throw new Error("tool " + toolId + " not in manifest");
              var emailLc = id.email.toLowerCase();
              var hasInclusion = Array.isArray(entry.audienceEmails) && entry.audienceEmails.length > 0;
              if (hasInclusion) {
                // Per-email audience — remove user's email from inclusion list.
                var before = entry.audienceEmails.length;
                entry.audienceEmails = entry.audienceEmails.filter(function (em) {
                  return String(em || "").toLowerCase() !== emailLc;
                });
                if (entry.audienceEmails.length === before) {
                  eli.log.event("tool", "admin_fleet_uninstall_not_in_audience", { toolId: toolId, email: id.email });
                }
              } else {
                // Broadcast audience (or no list) — add to exclude list.
                if (!Array.isArray(entry.audienceEmailExcludes)) entry.audienceEmailExcludes = [];
                var alreadyExcluded = entry.audienceEmailExcludes.some(function (em) {
                  return String(em || "").toLowerCase() === emailLc;
                });
                if (!alreadyExcluded) entry.audienceEmailExcludes.push(id.email);
              }
              manifest.lastUpdated = new Date().toISOString();
              var json = JSON.stringify(manifest, null, 2);
              var msg = "admin_fleet: uninstall " + toolId + " from " + id.email + " @ " +
                new Date().toISOString().replace("T", " ").replace(/\..*/, "");
              return _ghPut("tools-manifest-v3.json", json, msg, sha);
            }).then(function () {
              _toast("⏳ Pushing uninstall override…", "info");
              // Step 2: push force_redownload_tool override
              var overrideId = "fleet-uninstall-" + toolId + "-" + userId + "-" + Date.now();
              var entry = {
                id: overrideId,
                audienceEmails: [id.email],
                actions: [{ type: "force_redownload_tool", toolId: toolId }],
                pushedAt: new Date().toISOString(),
                pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
              };
              if (reason) entry.note = reason;
              return _pushOverride(entry);
            }).then(function () {
              _toast("✅ Uninstalled " + toolId + " from " + _displayName(userId), "ok");
              // Refresh local manifest cache so the excluded-tools section
              // shows the new exclusion on next render.
              return _fetchToolsManifest().then(function () { _renderDashboard(); });
            }).catch(function (err) {
              _toast("Uninstall failed: " + err.message, "err");
            });
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Tool re-grant (remove user from audienceEmailExcludes) ──────
  // Inverse of uninstall. Removes the user's email from a tool's
  // audienceEmailExcludes so they match the audience on next sync.
  // Optionally pushes a force_redownload override so the tool installs
  // immediately rather than waiting for the next manifest poll.
  function _showToolRegrant(userId, toolId) {
    if (typeof showEliDialog !== "function") return;
    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first", "err");
      return;
    }
    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Tool</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(toolId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_val_static" style="margin-top:4px;color:#475569;font-size:11px;">' +
          'Removes this user from the tool\'s audienceEmailExcludes. ' +
          'They\'ll match the audience again on next sync and the tool will auto-install. ' +
          'Optionally trigger immediate install via force_redownload.' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Also trigger immediate install?</label>' +
          '<label class="_eli3_af_radio"><input type="checkbox" id="_af_regrant_install" checked> Yes (push force_redownload override)</label>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason</label>' +
          '<input type="text" id="_af_regrant_reason" placeholder="(optional admin note)">' +
        '</div>' +
      '</div>';
    showEliDialog({
      variant: "neutral",
      icon: "↩️",
      title: "Re-grant tool access",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) { if (ov && ov.parentNode) ov.parentNode.removeChild(ov); },
        },
        {
          label: "Re-grant",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var triggerInstall = !!document.getElementById("_af_regrant_install").checked;
            var reason = (document.getElementById("_af_regrant_reason").value || "").trim();
            _toast("⏳ Editing manifest…", "info");
            // Step 1: edit manifest to remove user from excludes
            _ghGet("tools-manifest-v3.json").then(function (r) {
              if (!r) throw new Error("manifest not on CDN");
              var manifest;
              try { manifest = JSON.parse(_b64ToStr(r.content)); }
              catch (e) { throw new Error("manifest parse failed: " + e.message); }
              var sha = r.sha;
              var entry = (manifest.tools || []).find(function (t) { return t && t.id === toolId; });
              if (!entry) throw new Error("tool " + toolId + " not in manifest");
              if (!Array.isArray(entry.audienceEmailExcludes)) entry.audienceEmailExcludes = [];
              var emailLc = id.email.toLowerCase();
              var before = entry.audienceEmailExcludes.length;
              entry.audienceEmailExcludes = entry.audienceEmailExcludes.filter(function (em) {
                return String(em || "").toLowerCase() !== emailLc;
              });
              if (entry.audienceEmailExcludes.length === before) {
                eli.log.event("tool", "admin_fleet_regrant_not_excluded", { toolId: toolId, email: id.email });
              }
              if (entry.audienceEmailExcludes.length === 0) delete entry.audienceEmailExcludes;
              manifest.lastUpdated = new Date().toISOString();
              var json = JSON.stringify(manifest, null, 2);
              var msg = "admin_fleet: re-grant " + toolId + " to " + id.email + " @ " +
                new Date().toISOString().replace("T", " ").replace(/\..*/, "");
              return _ghPut("tools-manifest-v3.json", json, msg, sha);
            }).then(function () {
              if (!triggerInstall) return;
              // Step 2 (optional): push force_redownload to trigger install
              _toast("⏳ Pushing install override…", "info");
              var overrideId = "fleet-regrant-" + toolId + "-" + userId + "-" + Date.now();
              var entry = {
                id: overrideId,
                audienceEmails: [id.email],
                actions: [{ type: "force_redownload_tool", toolId: toolId }],
                pushedAt: new Date().toISOString(),
                pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
              };
              if (reason) entry.note = reason;
              return _pushOverride(entry);
            }).then(function () {
              _toast("✅ Re-granted " + toolId + " to " + _displayName(userId), "ok");
              return _fetchToolsManifest().then(function () { _renderDashboard(); });
            }).catch(function (err) {
              _toast("Re-grant failed: " + err.message, "err");
            });
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dashboard rendering ──────────────────────────────────────────
  function _renderDashboard() {
    var out = window.eli.ui.claimOutput();
    out.classList.add("eli-view-enter");

    var unresolved = _unresolvedUsers();
    var resolved = _allUsers().filter(function (uid) { return _lookup[uid]; });
    // 2026-05-23c+: build per-email override list with full audience
    // matching (was email-only — broadcasts pushed via the Audience
    // picker would never appear on any card). Same precedence as kernel:
    // excludes win first, then audience:"all" broadcast, then per-email.
    var allOverrides = (_adminOverrides && _adminOverrides.overrides) || [];
    var overridesByEmail = {};
    var allKnownEmails = {};
    resolved.forEach(function (uid) {
      var id = _identityFor(uid);
      if (id && id.email) allKnownEmails[id.email] = true;
    });
    function _overrideMatchesEmail(o, email) {
      if (Array.isArray(o.audienceEmailExcludes) && o.audienceEmailExcludes.indexOf(email) !== -1) return false;
      if (Array.isArray(o.audience) && o.audience.indexOf("all") !== -1) return true;
      if (Array.isArray(o.audienceEmails) && o.audienceEmails.indexOf(email) !== -1) return true;
      return false;
    }
    Object.keys(allKnownEmails).forEach(function (em) {
      overridesByEmail[em] = allOverrides.filter(function (o) { return _overrideMatchesEmail(o, em); });
    });

    function _renderUserCard(userId) {
      var id = _identityFor(userId);
      var fleet = _telemetryByUserId[userId];
      // Legacy fallback — for "AN-legacy" style synthetic IDs that have a
      // telemetry file but no fleet block yet, pull what we can from the
      // raw digest (days array, etc.) so the card isn't entirely empty.
      var legacyKey = _legacyUserKey(userId);
      var legacyDigest = legacyKey ? _telemetryRowsByUserKey[legacyKey] : null;
      var isLegacy = !!legacyDigest && !fleet;
      var nm = id ? _displayName(userId) : userId;
      var role = id && id.role ? id.role : "—";
      var status = id && id.status ? id.status : "—";
      var email = id && id.email ? id.email : "—";
      var lastSeen = fleet && fleet.lastSeenAt ? _ago(fleet.lastSeenAt)
        : (legacyDigest && legacyDigest.days && legacyDigest.days.length
            ? "legacy: last day " + legacyDigest.days[legacyDigest.days.length - 1].date
            : "never");
      // 2026-05-23: derive install date with fallbacks so unresolved /
      // legacy users still get a meaningful "first install" timestamp.
      // Priority:
      //   1. fleet.installedAt (set by eli_telemetry post-2026-05-23 kernel)
      //   2. earliest day in current digest (any user on telemetry)
      //   3. earliest day in legacy digest (pre-fleet-block users)
      //   4. "—"
      // The day-based fallbacks tag the value with "(earliest seen)" so
      // admin knows it's a proxy, not the exact install moment.
      var installedAt = "—";
      if (fleet && fleet.installedAt) {
        installedAt = new Date(fleet.installedAt).toLocaleDateString();
      } else {
        var earliestDay = null;
        // fleet might have its own days array carried alongside the
        // fleet block; check just in case.
        if (fleet && Array.isArray(fleet.days) && fleet.days.length) {
          earliestDay = fleet.days[0].date;
        } else if (legacyDigest && Array.isArray(legacyDigest.days) && legacyDigest.days.length) {
          earliestDay = legacyDigest.days[0].date;
        }
        if (earliestDay) {
          installedAt = new Date(earliestDay + "T00:00:00").toLocaleDateString() + " (earliest seen)";
        }
      }
      var aiModel = fleet && fleet.settings && fleet.settings.ai_model || "—";
      var kernelV = fleet && fleet.kernelVersion || "—";
      var toolCount = fleet && fleet.tools ? fleet.tools.length : 0;
      var activeOverrides = email !== "—" ? (overridesByEmail[email] || []) : [];

      var statusBadge = '<span class="_eli3_af_badge _eli3_af_badge_' + _esc(status) + '">' + _esc(status) + '</span>';
      var roleBadge = role !== "—" ? '<span class="_eli3_af_badge _eli3_af_badge_role">' + _esc(role) + '</span>' : '';
      var legacyBadge = isLegacy
        ? '<span class="_eli3_af_badge _eli3_af_badge_legacy" title="Telemetry exists but pre-dates fleet payload. Next push from this user will populate full fleet data.">⏳ legacy</span>'
        : '';

      var actionsHtml = '';
      if (id) {
        actionsHtml =
          '<button class="_eli3_af_btn _eli3_af_btn_primary" data-act="push-setting" data-uid="' + _esc(userId) + '">⚙️ Push setting</button>' +
          '<button class="_eli3_af_btn" data-act="send-notice" data-uid="' + _esc(userId) + '">📢 Send notice</button>' +
          '<button class="_eli3_af_btn" data-act="edit-identity" data-uid="' + _esc(userId) + '">✏️ Edit identity</button>' +
          '<button class="_eli3_af_btn _eli3_af_btn_danger" data-act="delete-user" data-uid="' + _esc(userId) + '" title="Remove identity + delete telemetry file from CDN">🗑 Delete user</button>';
      } else {
        // 2026-05-23: auto-link suggestion. If this unresolved user's
        // telemetry userKey matches an existing identity's derived
        // userKey, surface a one-click "Link to <name>" button. Common
        // after a wipe — old identity points to dead user_id, new
        // telemetry has new user_id but same email/initials.
        var unresolvedUserKey = _userKeyByUserId[userId];
        var matches = _identitiesForUserKey(unresolvedUserKey);
        var linkBtns = matches.map(function (pair) {
          var oldUid = pair[0];
          var idRec = pair[1];
          var nm = (idRec.firstName ? idRec.firstName + " " : "") +
            (idRec.lastName || (idRec.name || "").split(/\s+/).slice(-1)[0] || "");
          nm = nm.trim() || idRec.email || oldUid;
          return '<button class="_eli3_af_btn _eli3_af_btn_primary" ' +
            'data-act="link-to-identity" data-uid="' + _esc(userId) + '" data-old-uid="' + _esc(oldUid) + '" ' +
            'title="' + _esc(idRec.email) + ' currently maps to ' + _esc(oldUid) + ' — re-point to ' + _esc(userId) + ' (this user_id)">' +
            '🔗 Link to ' + _esc(nm) +
          '</button>';
        }).join("");
        actionsHtml =
          linkBtns +
          '<button class="_eli3_af_btn _eli3_af_btn_primary" data-act="add-identity" data-uid="' + _esc(userId) + '">🆕 Identify this user</button>' +
          '<button class="_eli3_af_btn _eli3_af_btn_danger" data-act="delete-user" data-uid="' + _esc(userId) + '" title="Delete the orphan telemetry file from CDN">🗑 Delete telemetry</button>';
      }

      // 2026-05-23c: collapsible + pin/unpin per tool. fleet.dashboardApps
      // is the user's RESOLVED pinned tile set (defaults included for
      // first-run users who never customized). fleet.dashboardCustomized
      // distinguishes "actively chose these pins" from "showing defaults
      // because they haven't touched dashboard settings yet" — the
      // distinction matters because pushing pin_tool on a non-customized
      // user transitions them into "customized" state (they lose all
      // future automatic default-pinning of new tools).
      var pinnedSet = {};
      if (fleet && Array.isArray(fleet.dashboardApps)) {
        fleet.dashboardApps.forEach(function (p) { pinnedSet[p] = true; });
      }
      var pinsCustomized = fleet && fleet.dashboardCustomized;
      var pinSourceNote = (fleet && Array.isArray(fleet.dashboardApps))
        ? (pinsCustomized
            ? '<span style="font-size:9px;color:#0d47a1;opacity:0.8;">user-customized</span>'
            : '<span style="font-size:9px;color:#94a3b8;opacity:0.9;">default pins (user has not customized)</span>')
        : '';
      var toolsList = "";
      if (fleet && fleet.tools && fleet.tools.length) {
        toolsList = '<details class="_eli3_af_tools">' +
          '<summary class="_eli3_af_tools_header">🧰 Tools (' + fleet.tools.length + ') — click to expand' +
            (pinSourceNote ? ' &nbsp; ' + pinSourceNote : '') +
          '</summary>' +
          '<div class="_eli3_af_tools_list">' +
            fleet.tools.map(function (t) {
              var disabledMark = t.disabled ? ' <span class="_eli3_af_tools_disabled">(disabled)</span>' : '';
              var isPinned = !!pinnedSet[t.id];
              return '<div class="_eli3_af_tools_row">' +
                '<span class="_eli3_af_tools_id">' + _esc(t.id) + '</span>' +
                (isPinned ? ' <span style="font-size:9px;color:#0d47a1;font-weight:700;" title="Pinned to user dashboard">📌</span>' : '') +
                disabledMark +
                (id ? (
                  '<div class="_eli3_af_tools_actions">' +
                    (isPinned
                      ? '<button class="_eli3_af_btn_mini" data-act="tool-unpin" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '" title="Remove from user\'s dashboard">📍 Unpin</button>'
                      : '<button class="_eli3_af_btn_mini" data-act="tool-pin" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '" title="Add to user\'s dashboard">📌 Pin</button>') +
                    (t.disabled
                      ? '<button class="_eli3_af_btn_mini" data-act="tool-enable" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '">▶ Enable</button>'
                      : '<button class="_eli3_af_btn_mini" data-act="tool-disable" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '">⏸ Disable</button>') +
                    '<button class="_eli3_af_btn_mini" data-act="tool-redownload" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '">↺ Re-DL</button>' +
                    '<button class="_eli3_af_btn_mini _eli3_af_btn_danger" data-act="tool-uninstall" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '" title="Remove from manifest audience + delete from IDB. Permanent until you re-add via manifest.">🗑 Uninstall</button>' +
                  '</div>'
                ) : '') +
              '</div>';
            }).join('') +
          '</div>' +
        '</details>';
      }

      // 2026-05-23c: full settings audit — list ALL registered settings,
      // not just those reporting current values via telemetry. Sensitive
      // ones (adminPushable: "encrypted") show "(encrypted)" as value
      // because their current values never leave the user's machine.
      // Each row has a "Push" button that opens the per-setting pusher.
      var settingsList = "";
      var registeredKeys = [];
      var registryEntries = {};
      try {
        if (window.eli && window.eli.settings && typeof window.eli.settings.dump === "function") {
          registryEntries = window.eli.settings.dump() || {};
          registeredKeys = Object.keys(registryEntries);
        }
      } catch (_e) {}
      if (registeredKeys.length || (fleet && fleet.settings)) {
        // Combine: every registered key + any extra telemetry-reported keys
        // (defensive — covers settings registered by tools we haven't loaded).
        var allKeys = registeredKeys.slice();
        if (fleet && fleet.settings) {
          Object.keys(fleet.settings).forEach(function (k) {
            if (allKeys.indexOf(k) === -1) allKeys.push(k);
          });
        }
        allKeys.sort();
        settingsList = '<details class="_eli3_af_settings">' +
          '<summary class="_eli3_af_settings_header">⚙️ Settings (' + allKeys.length + ') — click to expand</summary>' +
          '<div class="_eli3_af_settings_list">' +
            allKeys.map(function (k) {
              var entry = registryEntries[k] || {};
              var isEncrypted = entry.adminPushable === "encrypted";
              var hasFleetValue = fleet && fleet.settings && Object.prototype.hasOwnProperty.call(fleet.settings, k);
              var valDisplay;
              if (isEncrypted) {
                valDisplay = '<span style="opacity:0.7;font-style:italic">(encrypted — push-only)</span>';
              } else if (hasFleetValue) {
                valDisplay = _esc(String(fleet.settings[k]));
              } else {
                valDisplay = '<span style="opacity:0.5">—</span>';
              }
              var pushBtn = id
                ? '<button class="_eli3_af_btn_mini" data-act="push-setting-key" data-uid="' + _esc(userId) + '" data-key="' + _esc(k) + '">' +
                    (isEncrypted ? '🔐 Push' : '📤 Push') +
                  '</button>'
                : '';
              return '<div class="_eli3_af_settings_row">' +
                '<span class="_eli3_af_settings_key">' + _esc(k) + ':</span> ' +
                '<span class="_eli3_af_settings_val">' + valDisplay + '</span> ' +
                pushBtn +
              '</div>';
            }).join('') +
          '</div>' +
        '</details>';
      }

      // 2026-05-23c+: applied-status lookup. fleet.appliedOverrides is
      // pushed by eli_telemetry on every digest, sourced from each user's
      // local _admin_applied_<id> markers. If telemetry hasn't pushed
      // since the override was applied, status lags behind; otherwise
      // tells admin exactly which overrides have landed on this user.
      var appliedById = {};
      if (fleet && Array.isArray(fleet.appliedOverrides)) {
        fleet.appliedOverrides.forEach(function (a) { if (a && a.id) appliedById[a.id] = a; });
      }
      var overridesList = "";
      if (activeOverrides.length) {
        overridesList = '<div class="_eli3_af_overrides">' +
          '<div class="_eli3_af_overrides_header">Active admin pushes (' + activeOverrides.length + ')</div>' +
          activeOverrides.map(function (o) {
            var actionSummary = (o.actions || []).map(function (a) {
              if (a.type === "set_setting") return a.key + " = " + JSON.stringify(a.value) + " (" + (a.force === true ? "force" : a.force === "reset" ? "reset" : "soft") + ")";
              if (a.type === "set_setting_encrypted") return "🔐 " + a.key + " (encrypted)";
              if (a.type === "disable_tool") return "disable " + a.toolId;
              if (a.type === "enable_tool") return "enable " + a.toolId;
              if (a.type === "force_redownload_tool") return "re-download " + a.toolId;
              if (a.type === "pin_tool") return "pin " + a.toolId;
              if (a.type === "unpin_tool") return "unpin " + a.toolId;
              if (a.type === "notice") return "📢 notice: " + (a.title || "(untitled)");
              if (a.type === "clear_setting_override") return "clear admin " + a.key;
              if (a.type === "reload_kernel") return "reload kernel";
              if (a.type === "reset_onboarding") return "reset onboarding";
              return a.type;
            }).join("; ");
            // Status chip — green Applied (with ago) if marker exists for
            // this user, amber Pending otherwise. Snapshot reflects the
            // user's LAST telemetry push (lag = up to 12h or until next
            // reload, whichever sooner).
            var applied = appliedById[o.id];
            var statusChip = applied
              ? '<span class="_eli3_af_chip _eli3_af_chip_ok" title="Applied ' + (applied.at ? new Date(applied.at).toLocaleString() : "?") + '">✓ Applied' + (applied.at ? ' ' + _ago(applied.at) : '') + '</span>'
              : '<span class="_eli3_af_chip _eli3_af_chip_pending" title="Not yet applied by this user (or telemetry hasn\'t pushed since)">⏳ Pending</span>';
            // 2026-05-23c+: Revert button — only meaningful for setting
            // overrides where the original mode was force/soft (those
            // wrote to an admin layer that clear_setting_override can
            // strip). "reset" mode wrote to user pref — no clean revert
            // path, so we hide the button there.
            var canRevert = (o.actions || []).some(function (a) {
              return (a.type === "set_setting" || a.type === "set_setting_encrypted")
                && a.force !== "reset";
            });
            var revertBtn = canRevert
              ? '<button class="_eli3_af_btn_mini" data-act="revert-override" data-oid="' + _esc(o.id) + '" title="Push clear_setting_override + remove this override from CDN">🔄 Revert</button>'
              : '';
            return '<div class="_eli3_af_overrides_row">' +
              '<span>' + _esc(actionSummary) + '</span>' +
              ' ' + statusChip +
              ' ' + revertBtn +
              ' <button class="_eli3_af_btn_mini _eli3_af_btn_danger" data-act="remove-override" data-oid="' + _esc(o.id) + '" title="Remove from CDN only — does NOT undo on targets that already applied">🗑 Remove</button>' +
            '</div>';
          }).join('') +
        '</div>';
      }

      // Prominent installed-tools line — shows top N tool IDs at a glance,
      // with "+N more" if list is longer. Full per-tool action buttons
      // remain below in the toolsList section.
      var installedToolsLine = "";
      if (fleet && fleet.tools && fleet.tools.length) {
        var visibleIds = fleet.tools.slice(0, 8).map(function (t) {
          return t.disabled ? '<span style="opacity:0.5;text-decoration:line-through">' + _esc(t.id) + '</span>' : _esc(t.id);
        });
        var more = fleet.tools.length > 8 ? ' <span style="opacity:0.6;">+' + (fleet.tools.length - 8) + ' more</span>' : '';
        installedToolsLine =
          '<div class="_eli3_af_installed_line" title="Tools currently installed on this user\'s machine">' +
            '<span class="_eli3_af_installed_label">Installed (' + fleet.tools.length + '):</span> ' +
            visibleIds.join(", ") + more +
          '</div>';
      } else if (legacyDigest) {
        installedToolsLine =
          '<div class="_eli3_af_installed_line _eli3_af_installed_line_legacy" title="Telemetry pre-dates fleet payload; tool list will populate after their next push">' +
            '<span class="_eli3_af_installed_label">Installed:</span> ' +
            '<span style="opacity:0.6">(unknown — needs fleet-block push)</span>' +
          '</div>';
      }

      // Excluded tools — tools where this user is in audienceEmailExcludes
      // on the manifest. Each gets a Re-grant button.
      var excludedList = "";
      var excluded = _excludedToolsForUser(userId);
      if (excluded.length) {
        excludedList = '<div class="_eli3_af_excluded">' +
          '<div class="_eli3_af_excluded_header">🚫 Excluded by admin (' + excluded.length + ')</div>' +
          excluded.map(function (tid) {
            return '<div class="_eli3_af_excluded_row">' +
              '<span class="_eli3_af_excluded_id">' + _esc(tid) + '</span>' +
              '<button class="_eli3_af_btn_mini" data-act="tool-regrant" data-uid="' + _esc(userId) + '" data-tool="' + _esc(tid) + '">↩️ Re-grant</button>' +
            '</div>';
          }).join('') +
        '</div>';
      }

      return '<div class="_eli3_af_card" data-uid="' + _esc(userId) + '">' +
        '<div class="_eli3_af_card_header">' +
          '<div class="_eli3_af_card_name">' + _esc(nm) +
            ' <code class="_eli3_af_card_uid" title="User ID — anonymous install identifier">' + _esc(userId) + '</code>' +
          '</div>' +
          '<div class="_eli3_af_card_badges">' + roleBadge + statusBadge + legacyBadge + '</div>' +
        '</div>' +
        '<div class="_eli3_af_card_meta">' +
          '<span title="User ID">' + _esc(userId) + '</span>' +
          ' · <span title="Email">' + _esc(email) + '</span>' +
          ' · <span title="Last telemetry upload">last seen ' + _esc(lastSeen) + '</span>' +
          ' · <span title="Install date">installed ' + _esc(installedAt) + '</span>' +
          ' · <span title="Kernel version">' + _esc(kernelV) + '</span>' +
          ' · <span title="Tools count">' + toolCount + ' tools</span>' +
          ' · <span title="Current AI model">model: ' + _esc(aiModel) + '</span>' +
        '</div>' +
        installedToolsLine +
        '<div class="_eli3_af_card_actions">' + actionsHtml + '</div>' +
        settingsList +
        toolsList +
        excludedList +
        overridesList +
      '</div>';
    }

    var headerHtml =
      '<div class="_eli3_af_header">' +
        '<div class="_eli3_af_header_title">' +
          '<span class="_eli3_af_header_icon">👥</span>' +
          '<span>ELI Fleet</span>' +
        '</div>' +
        '<div class="_eli3_af_header_meta">' +
          _allUsers().length + ' users · ' +
          unresolved.length + ' unresolved · ' +
          (_adminOverrides && _adminOverrides.overrides ? _adminOverrides.overrides.length : 0) + ' active pushes' +
        '</div>' +
        '<div class="_eli3_af_header_actions">' +
          '<button class="_eli3_af_btn" id="_af_broadcast">📢 Broadcast</button>' +
          '<button class="_eli3_af_btn" id="_af_refresh">🔄 Refresh</button>' +
          '<button class="_eli3_af_btn" id="_af_close">✕ Close</button>' +
        '</div>' +
      '</div>';

    var unresolvedHtml = "";
    if (unresolved.length) {
      unresolvedHtml = '<div class="_eli3_af_section">' +
        '<div class="_eli3_af_section_header">🆕 Unresolved users — click "Identify" to add them to your lookup</div>' +
        unresolved.map(_renderUserCard).join("") +
      '</div>';
    }

    var resolvedHtml = '<div class="_eli3_af_section">' +
      '<div class="_eli3_af_section_header">Resolved users (' + resolved.length + ')</div>' +
      (resolved.length ? resolved.map(_renderUserCard).join("") :
        '<div class="_eli3_af_empty">No users in the lookup table yet. Identify one above to get started.</div>') +
    '</div>';

    out.innerHTML =
      '<div class="_eli3_af_root">' +
        headerHtml +
        // 2026-05-23: resolved (identified) users first, unresolved below.
        // Reduces clutter for admins who mostly look at known fleet.
        resolvedHtml +
        unresolvedHtml +
      '</div>';

    // Wire actions
    document.getElementById("_af_refresh").onclick = function () { _launch(true); };
    document.getElementById("_af_broadcast").onclick = function () { _showNoticePusher(null); };
    document.getElementById("_af_close").onclick = function () {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    };
    // 2026-05-23 bug fix: use .onclick assignment (replaces) instead of
    // addEventListener (stacks). _renderDashboard() runs after every save /
    // push / refresh; with addEventListener each re-render added a NEW
    // handler, so a single click opened N stacked dialogs (one per render
    // since boot). User saw "click Cancel 2-3 times to dismiss" + backdrop
    // dimming visibly getting lighter as each overlay peeled away.
    out.onclick = function (ev) {
      var t = ev.target;
      while (t && t !== out) {
        var act = t.getAttribute && t.getAttribute("data-act");
        if (act) {
          var uid = t.getAttribute("data-uid");
          if (act === "add-identity") return _showIdentityEditor(uid, true);
          if (act === "edit-identity") return _showIdentityEditor(uid, false);
          if (act === "delete-user") return _showDeleteUserConfirm(uid);
          if (act === "link-to-identity") return _linkUserToIdentity(uid, t.getAttribute("data-old-uid"));
          if (act === "push-setting") return _showSettingPusher(uid);
          if (act === "push-setting-key") return _showSettingPusher(uid, t.getAttribute("data-key"));
          if (act === "send-notice") return _showNoticePusher(uid);
          if (act === "tool-disable") return _showToolPusher(uid, t.getAttribute("data-tool"), "disable_tool");
          if (act === "tool-enable") return _showToolPusher(uid, t.getAttribute("data-tool"), "enable_tool");
          if (act === "tool-redownload") return _showToolPusher(uid, t.getAttribute("data-tool"), "force_redownload_tool");
          if (act === "tool-uninstall") return _showToolUninstaller(uid, t.getAttribute("data-tool"));
          if (act === "tool-regrant") return _showToolRegrant(uid, t.getAttribute("data-tool"));
          if (act === "tool-pin") return _pushPinAction(uid, t.getAttribute("data-tool"), true);
          if (act === "tool-unpin") return _pushPinAction(uid, t.getAttribute("data-tool"), false);
          if (act === "remove-override") {
            var oid = t.getAttribute("data-oid");
            if (!oid) return;
            _toast("⏳ Removing override…", "info");
            _removeOverride(oid).then(function (ok) {
              if (ok) _toast("✅ Override removed", "ok");
              _renderDashboard();
            }).catch(function (err) { _toast("Remove failed: " + err.message, "err"); });
            return;
          }
          if (act === "revert-override") {
            var roid = t.getAttribute("data-oid");
            if (!roid) return;
            return _revertOverride(roid);
          }
        }
        t = t.parentNode;
      }
    };
  }

  function _launch(force) {
    _toast("⏳ Loading fleet data…", "info");
    return _bootstrap().then(function () {
      _renderDashboard();
      eli.log.event("tool", "admin_fleet_loaded", {
        users: _allUsers().length,
        unresolved: _unresolvedUsers().length,
        overrides: (_adminOverrides && _adminOverrides.overrides || []).length,
      });
    }).catch(function (err) {
      _toast("Fleet load failed: " + (err.message || "unknown"), "err");
      eli.log.event("tool", "admin_fleet_load_failed", { msg: err && err.message });
      // Render a fallback message
      var out = window.eli.ui.claimOutput();
      out.innerHTML =
        '<div class="_eli3_af_root">' +
          '<div class="_eli3_af_error">' +
            '<h2>👥 ELI Fleet — Setup needed</h2>' +
            '<p>' + _esc(err.message || "Unknown error") + '</p>' +
            '<p>Make sure both <code>eli_user_github_pat</code> and <code>eli_admin_password</code> are set ' +
              '(usually via importing a credentials bundle in Admin Library Publisher).</p>' +
            '<button class="_eli3_af_btn" id="_af_retry">🔄 Retry</button>' +
          '</div>' +
        '</div>';
      document.getElementById("_af_retry").onclick = function () { _launch(); };
    });
  }

  // ── Tile registration ────────────────────────────────────────────
  if (eli.register) {
    eli.register({
      tile: {
        app_admin_fleet: eli.events.guard ? eli.events.guard(function () { _launch(); }, "admin_fleet.tile") : function () { _launch(); },
      },
    });
  }

  eli.log.event("tool", "admin_fleet_initialized", {});
}

jsonTools.css:
/* admin_fleet — fleet dashboard styling
   Light palette in both themes (per CLAUDE.md tools+dialogs rule). */

._eli3_af_root {
  font: 13px/1.4 'Inter', system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 16px;
  min-height: 100vh;
  box-sizing: border-box;
  /* 2026-05-23: kernel's .output-area is a flex column with transparent
     bg — without flex grow, tool sizes to content and scroll exposes the
     body's navy dashboard bg below. */
  flex: 1 0 auto;
}
.beta-ui-active .output-area:has(> ._eli3_af_root),
.output-area:has(> ._eli3_af_root) {
  background: #f8fafc !important;
}

._eli3_af_header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  border-radius: 0;
  margin-bottom: 14px;
}
._eli3_af_header_title {
  font-family: 'Georgia', serif;
  font-size: 18px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}
._eli3_af_header_icon { font-size: 20px; }
._eli3_af_header_meta {
  font-size: 11px;
  color: #cbd5e1;
  letter-spacing: 0.5px;
  flex: 1;
}
._eli3_af_header_actions {
  display: flex;
  gap: 6px;
}
._eli3_af_header_actions ._eli3_af_btn {
  background: rgba(255,255,255,0.15);
  border-color: rgba(255,255,255,0.3);
  color: #fff;
}
._eli3_af_header_actions ._eli3_af_btn:hover {
  background: rgba(255,255,255,0.25);
}

._eli3_af_section {
  margin-bottom: 16px;
}
._eli3_af_section_header {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #475569;
  padding: 8px 4px;
  border-bottom: 1px solid #cbd5e1;
  margin-bottom: 8px;
}
._eli3_af_empty {
  padding: 24px 12px;
  text-align: center;
  color: #94a3b8;
  font-size: 12px;
}

._eli3_af_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #1565c0;
  padding: 12px 14px;
  margin-bottom: 8px;
}
._eli3_af_card[data-uid] ._eli3_af_card_header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 4px;
}
._eli3_af_card_name {
  font: 700 14px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_af_card_badges {
  display: flex;
  gap: 4px;
  flex-shrink: 0;
}
._eli3_af_badge {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 6px;
  border-radius: 2px;
}
._eli3_af_badge_role {
  background: #e0e7ff; color: #3730a3; border: 1px solid #c7d2fe;
}
._eli3_af_badge_active {
  background: #dcfce7; color: #14532d; border: 1px solid #86efac;
}
._eli3_af_badge_trial {
  background: #fef3c7; color: #92400e; border: 1px solid #fde68a;
}
._eli3_af_badge_offboarded {
  background: #f1f5f9; color: #64748b; border: 1px solid #cbd5e1;
}
._eli3_af_badge_legacy {
  background: #fde68a; color: #78350f; border: 1px solid #fbbf24;
}

._eli3_af_card_meta {
  font: 500 10.5px/1.4 'Inter', sans-serif;
  color: #64748b;
  margin-bottom: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 0;
}
._eli3_af_card_meta span { white-space: nowrap; }

._eli3_af_card_actions {
  display: flex;
  gap: 6px;
  margin: 6px 0;
  flex-wrap: wrap;
}

._eli3_af_btn {
  font: 600 11px/1 'Inter', sans-serif;
  padding: 6px 10px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  border-bottom-width: 2px;
  color: #0f172a;
  cursor: pointer;
  border-radius: 3px;
  transition: filter 0.12s;
}
._eli3_af_btn:hover { filter: brightness(0.97); }
._eli3_af_btn_primary {
  background: linear-gradient(180deg, #1565c0 0%, #0d47a1 100%);
  border-color: #0d47a1;
  color: #fff;
}
._eli3_af_btn_primary:hover { filter: brightness(1.08); }

._eli3_af_btn_mini {
  font: 600 10px/1 'Inter', sans-serif;
  padding: 3px 6px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  color: #0f172a;
  cursor: pointer;
  border-radius: 2px;
  transition: filter 0.12s;
}
._eli3_af_btn_mini:hover { filter: brightness(0.95); }
._eli3_af_btn_danger {
  background: linear-gradient(180deg, #fef2f2 0%, #fee2e2 100%);
  border-color: #fca5a5;
  color: #991b1b;
}

._eli3_af_settings,
._eli3_af_tools,
._eli3_af_overrides {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
  font-size: 11px;
}
._eli3_af_settings_header,
._eli3_af_tools_header,
._eli3_af_overrides_header {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #475569;
  margin-bottom: 4px;
}
/* 2026-05-23c: collapsible-section styling for <details>/<summary>. */
summary._eli3_af_settings_header,
summary._eli3_af_tools_header {
  cursor: pointer;
  padding: 4px 6px;
  margin-bottom: 0;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 3px;
  user-select: none;
  list-style: revert;
}
summary._eli3_af_settings_header:hover,
summary._eli3_af_tools_header:hover {
  background: #f1f5f9;
}
details[open] > summary._eli3_af_settings_header,
details[open] > summary._eli3_af_tools_header {
  margin-bottom: 6px;
}
/* 2026-05-23c+: status chips on active admin pushes. */
._eli3_af_chip {
  display: inline-block;
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 6px;
  border-radius: 10px;
  border: 1px solid;
  white-space: nowrap;
}
._eli3_af_chip_ok {
  background: #dcfce7;
  color: #14532d;
  border-color: #86efac;
}
._eli3_af_chip_pending {
  background: #fef3c7;
  color: #92400e;
  border-color: #fde68a;
}
/* Legacy/warning callout used by the encrypted-push and setting dialogs. */
._eli3_af_warn {
  padding: 8px 10px;
  background: #fef3c7;
  border: 1px solid #fde68a;
  border-left: 3px solid #f59e0b;
  border-radius: 3px;
  font-size: 11px;
  color: #92400e;
  margin-bottom: 6px;
}
._eli3_af_settings_list,
._eli3_af_tools_list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px 12px;
}
._eli3_af_settings_row,
._eli3_af_tools_row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  color: #475569;
  padding: 1px 0;
}
._eli3_af_settings_key { font-weight: 700; color: #0f172a; }
._eli3_af_settings_val { color: #1565c0; }
._eli3_af_tools_id { flex: 1; color: #0f172a; }
._eli3_af_tools_disabled { color: #b91c1c; font-weight: 700; font-size: 9px; }
._eli3_af_tools_actions { display: flex; gap: 2px; }

._eli3_af_overrides_row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 3px 6px;
  background: #fef3c7;
  border: 1px solid #fde68a;
  margin-bottom: 3px;
  font-size: 10.5px;
  color: #92400e;
}

/* Installed-tools line — at-a-glance list of tool IDs in card meta */
._eli3_af_installed_line {
  margin: 4px 0 4px 0;
  padding: 6px 8px;
  background: #f8fafc;
  border-left: 3px solid #1565c0;
  font: 500 11px/1.5 'Inter', sans-serif;
  color: #475569;
  word-break: break-all;
}
._eli3_af_installed_line_legacy {
  border-left-color: #fbbf24;
}
._eli3_af_installed_label {
  font: 700 9.5px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #0f172a;
  margin-right: 4px;
}

/* Excluded-tools section — tools where user is in audienceEmailExcludes */
._eli3_af_excluded {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
}
._eli3_af_excluded_header {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #b91c1c;
  margin-bottom: 4px;
}
._eli3_af_excluded_row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 3px 6px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  margin-bottom: 3px;
  font-size: 10.5px;
  color: #991b1b;
}
._eli3_af_excluded_id { flex: 1; font-weight: 600; }

._eli3_af_form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
._eli3_af_form_row {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 10px;
  align-items: center;
}
._eli3_af_form_row label {
  font: 700 11px/1.2 'Inter', sans-serif;
  color: #475569;
  text-transform: uppercase;
